// Package postgres keeps the DPoP proofs garam accepted and the nonce
// of each period in PostgreSQL via jackc/pgx (ADR-0191 decisions 4
// and 5), so every replica refuses a replay and accepts any replica's
// nonce.
// The queries are generated by sqlc from queries.sql.
package postgres

import (
	"context"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/platform/internal/dpop"
	"github.com/garamsh/garam/platform/internal/dpop/postgres/db"
	"github.com/garamsh/garam/platform/internal/pgxerr"
)

// Store satisfies [dpop.Store].
type Store struct {
	q *db.Queries
}

var _ dpop.Store = (*Store)(nil)

// New returns a Store over pool.
func New(pool *pgxpool.Pool) *Store {
	return &Store{q: db.New(pool)}
}

func interval(d time.Duration) pgtype.Interval {
	return pgtype.Interval{Microseconds: d.Microseconds(), Valid: true}
}

// SpendJTI sweeps every expired jti, then records jti for jkt unless a
// row already holds it. The primary key decides between two replicas
// spending the same jti at once.
func (s *Store) SpendJTI(ctx context.Context, jkt, jti string, ttl time.Duration) (bool, error) {
	if err := s.q.SweepJTIs(ctx); err != nil {
		return false, pgxerr.Classify(err, "sweep dpop jtis", nil, nil)
	}
	_, err := s.q.SpendJTI(ctx, db.SpendJTIParams{Jkt: jkt, Jti: jti, Ttl: interval(ttl)})
	if errors.Is(err, pgx.ErrNoRows) {
		return false, nil
	}
	if err != nil {
		return false, pgxerr.Classify(err, "spend dpop jti", nil, nil)
	}
	return true, nil
}

// CurrentNonce reads the current period's nonce, and only where the
// period has none sweeps the old periods and keeps candidate, the
// primary key deciding between two replicas keeping one at once; the
// one kept is read back.
func (s *Store) CurrentNonce(ctx context.Context, candidate string, period time.Duration) (string, error) {
	seconds := int64(period / time.Second)
	nonce, err := s.q.CurrentNonce(ctx, seconds)
	if err == nil {
		return nonce, nil
	}
	if !errors.Is(err, pgx.ErrNoRows) {
		return "", pgxerr.Classify(err, "read dpop nonce", nil, nil)
	}
	if err := s.q.SweepNonces(ctx, seconds); err != nil {
		return "", pgxerr.Classify(err, "sweep dpop nonces", nil, nil)
	}
	if err := s.q.KeepNonce(ctx, db.KeepNonceParams{Seconds: seconds, Nonce: candidate}); err != nil {
		return "", pgxerr.Classify(err, "keep dpop nonce", nil, nil)
	}
	nonce, err = s.q.CurrentNonce(ctx, seconds)
	if err != nil {
		return "", pgxerr.Classify(err, "read dpop nonce", nil, nil)
	}
	return nonce, nil
}

// NonceLive answers whether a row holds nonce for the current period
// or the previous one.
func (s *Store) NonceLive(ctx context.Context, nonce string, period time.Duration) (bool, error) {
	live, err := s.q.NonceLive(ctx, db.NonceLiveParams{Nonce: nonce, Seconds: int64(period / time.Second)})
	if err != nil {
		return false, pgxerr.Classify(err, "read dpop nonce", nil, nil)
	}
	return live, nil
}
